Compiles clean on solc 0.8.28 (the unchecked-transfer warnings existed in the original too). The fixed contract, saved at `exec/Vault.sol`:

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

contract Vault {
    IERC20 public immutable asset;
    uint256 public totalShares;
    mapping(address => uint256) public shares;

    constructor(address _asset) { asset = IERC20(_asset); }

    function deposit(uint256 amount) external returns (uint256 s) {
        uint256 total = asset.balanceOf(address(this));
        // Virtual shares/assets offset (OZ ERC4626-style): pricing as if the
        // vault already held 1 extra share and 1 extra asset. This makes the
        // classic "deposit 1 wei then donate" inflation attack unprofitable —
        // an attacker's donation gets diluted against the virtual share
        // instead of zeroing out the next depositor's share count.
        s = (amount * (totalShares + 1)) / (total + 1);
        shares[msg.sender] += s;
        totalShares += s;
        asset.transferFrom(msg.sender, address(this), amount);
    }

    function withdraw(uint256 s) external returns (uint256 amount) {
        uint256 total = asset.balanceOf(address(this));
        amount = (s * (total + 1)) / (totalShares + 1);
        shares[msg.sender] -= s;
        totalShares -= s;
        asset.transfer(msg.sender, amount);
    }
}
```

**Bug:** `deposit` priced shares against `total = balanceOf(vault)`, so a first depositor of 1 wei followed by a large direct token donation inflates the share price to the point where the next depositor's `amount * totalShares / total` rounds down to 0 — they mint nothing and lose their whole deposit.

**Fix:** add a virtual 1 share / 1 asset offset to both the mint and redemption formulas. It also removes the implicit `total == 0` special case (division is now always by `total + 1`, never zero). Verified: two equal deposits mint equal shares and each depositor can withdraw exactly what they put in; running the attack (1 wei deposit + large donation) now leaves the attacker diluted against the virtual share and unable to profit, while the victim's deposit still mints shares.
